/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

ID_Set * can_v_id_set_copy (ID_Set * const id_set)
{
  ID_Set * set = can_v_id_set_create () ;

  ID_Set_Iterator  iter     ;
  ID_Range       * id_range ;

  for (can_v_id_set_iterator_init (& iter , & id_range , id_set , ITER_L2R) ; id_range ; can_v_id_set_iterator_next (& iter , & id_range))
    {
      can_v_id_set_insert_rhs (set , can_v_id_range_copy (id_range)) ;
    }

  return set ;
}

